package com.bare.folders.manifest; public final class LatestManifestState { private final String manifestId; private final long size; private final boolean valid,fromCache; public LatestManifestState(String manifestId,long size,boolean valid,boolean fromCache){this.manifestId=manifestId;this.size=Math.max(0,size);this.valid=valid;this.fromCache=fromCache;} public String getManifestId(){return manifestId;} public long getSize(){return size;} public boolean isValid(){return valid;} public boolean isFromCache(){return fromCache;} }